// Checks catalog-gettext's committed plural formulas (src/plugins/catalog-gettext/plural-forms.json),
// generated by `pnpm update:gettext-plurals`, so a bad update or a hand edit can't slip in.
import { readFileSync } from 'node:fs';
import { describe, expect, it } from 'vitest';
import { buildPluralForms, serializePluralForms, type PluralFormsFile } from './gettext-plurals.ts';

const text = readFileSync(
  new URL('../src/plugins/catalog-gettext/plural-forms.json', import.meta.url),
  'utf8',
);
const data = JSON.parse(text) as PluralFormsFile;

describe('the gettext plural formulas', () => {
  it('are exactly what the generator writes (no hand edits, stable formatting)', () => {
    expect(serializePluralForms(data)).toBe(text);
  });

  it('record when they were generated, from what, and under which licenses', () => {
    expect(data.generated).toMatch(/^\d{4}-\d{2}-\d{2}$/);
    expect(data.sources).toEqual([
      {
        name: expect.stringContaining('CLDR') as unknown,
        url: expect.stringMatching(/^https:\/\/php-gettext\.github\.io\//) as unknown,
        license: 'MIT; CLDR data: Unicode-3.0',
      },
    ]);
  });

  it('cover the languages Paper Lion is used for, with their forms', () => {
    expect(Object.keys(data.languages).length).toBeGreaterThan(200);
    expect(data.languages.he).toEqual({ plurals: 3, formula: 'n == 1 ? 0 : n == 2 ? 1 : 2' });
    expect(data.languages.ar?.plurals).toBe(6);
    expect(data.languages.ja).toEqual({ plurals: 1, formula: '0' });
    expect(data.languages.pt_PT?.plurals).toBe(3);
  });
});

describe('buildPluralForms', () => {
  it('keeps each language’s count and standard formula, sorted by name', () => {
    const built = buildPluralForms(
      {
        he: { plurals: 3, formulas: { standard: 'n == 1 ? 0 : n == 2 ? 1 : 2' } },
        en: { plurals: 2, formulas: { standard: 'n != 1' } },
      },
      '2026-11-03',
      { name: 'CLDR', url: 'https://example.org' },
    );
    expect(Object.keys(built.languages)).toEqual(['en', 'he']);
    expect(built.languages.en).toEqual({ plurals: 2, formula: 'n != 1' });
    expect(serializePluralForms(built)).toBe(
      [
        '{',
        '  "generated": "2026-11-03",',
        '  "sources": [{"name":"CLDR","url":"https://example.org","license":"MIT; CLDR data: Unicode-3.0"}],',
        '  "languages": {',
        '    "en": {"plurals":2,"formula":"n != 1"},',
        '    "he": {"plurals":3,"formula":"n == 1 ? 0 : n == 2 ? 1 : 2"}',
        '  }',
        '}',
        '',
      ].join('\n'),
    );
  });
});
